begin;
update nexora.modules set description='Construa interfaces web com HTML semântico e CSS moderno, cobrindo acessibilidade, layout, responsividade e publicação de uma landing page profissional.' where course_id=(select id from nexora.courses where slug='programador-master') and position=3;
update nexora.lessons set objective='Construir um documento HTML válido e explicar o papel de doctype, html, head e body na estrutura de uma página.',estimated_minutes=30,lab_type='html',lab_config='{}'::jsonb,content='[{"type":"story","title":"Contexto","body":"Uma página abre no navegador, mas título, metadados e conteúdo estão misturados. Antes de estilizar, é preciso organizar a estrutura do documento."},{"type":"concept","title":"Introdução ao HTML e estrutura básica","body":"HTML descreve a estrutura e o significado do conteúdo. O navegador interpreta uma árvore de elementos, não uma sequência visual de linhas. A declaração doctype ativa o modo moderno; html envolve o documento; head reúne metadados e recursos; body contém o que faz parte da interface. Essa base influencia acessibilidade, SEO, manutenção e a forma como CSS e JavaScript encontram elementos."},{"type":"mechanics","title":"Como aplicar","items":["Use uma estrutura completa desde o primeiro arquivo.","Mantenha metadados no head e conteúdo no body.","Defina idioma no elemento html.","Indente para tornar relações pai-filho visíveis."]},{"type":"example","title":"Exemplo","body":"<!doctype html>\\n<html lang=\"pt-BR\">\\n<head>\\n  <meta charset=\"utf-8\">\\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\\n  <title>Projeto LC</title>\\n</head>\\n<body>\\n  <main><h1>Olá, Web</h1></main>\\n</body>\\n</html>","language":"html"},{"type":"mistake","title":"Erro comum","body":"Começar usando divs e estilos sem definir a estrutura do documento. Isso mascara problemas de semântica e responsividade que reaparecem depois."},{"type":"guided","question":"Qual elemento deve conter o conteúdo principal visível da página?","options":["body","head","meta"],"answer":0,"hint":"Escolha a alternativa coerente com a estrutura ensinada.","feedback":"Correto. Você aplicou a decisão estrutural da aula.","feedback_incorrect":"Revise a explicação e o exemplo antes de tentar novamente."},{"type":"recap","items":["Construir um documento HTML válido e explicar o papel de doctype, html, head e body na estrutura de uma página.","Use uma estrutura completa desde o primeiro arquivo.","Mantenha metadados no head e conteúdo no body.","Defina idioma no elemento html."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=3) and title='Introdução ao HTML e estrutura básica';
update nexora.lessons set objective='Escolher elementos HTML adequados para títulos, parágrafos, ênfase, agrupamento e conteúdo genérico, evitando marcação sem significado.',estimated_minutes=32,lab_type='html',lab_config='{}'::jsonb,content='[{"type":"story","title":"Contexto","body":"Um layout usa div para títulos, textos, botões e listas. Visualmente pode funcionar, mas a estrutura não comunica o papel de cada conteúdo."},{"type":"concept","title":"Tags e elementos HTML fundamentais","body":"Elementos HTML carregam significado além da aparência. Títulos h1–h6 criam hierarquia; p representa parágrafos; strong sinaliza importância; em adiciona ênfase; button representa ação. Div e span são contêineres genéricos úteis quando não existe elemento semântico apropriado. Escolher a tag pelo papel do conteúdo melhora navegação por leitores de tela, manutenção e previsibilidade do CSS."},{"type":"mechanics","title":"Como aplicar","items":["Escolha a tag pelo significado, não pelo estilo padrão.","Mantenha hierarquia de títulos coerente.","Use button para ações e a para navegação.","Reserve div/span para agrupamentos realmente genéricos."]},{"type":"example","title":"Exemplo","body":"<article>\\n  <h2>Curso de JavaScript</h2>\\n  <p>Aprenda a criar interfaces interativas.</p>\\n  <button type=\"button\">Começar</button>\\n</article>","language":"html"},{"type":"mistake","title":"Erro comum","body":"Usar uma tag porque ''fica grande'' ou ''fica em negrito''. Aparência pertence ao CSS; HTML deve expressar função."},{"type":"guided","question":"Qual elemento representa melhor uma ação que acontece na própria página?","options":["button","div","h2"],"answer":0,"hint":"Escolha a alternativa coerente com a estrutura ensinada.","feedback":"Correto. Você aplicou a decisão estrutural da aula.","feedback_incorrect":"Revise a explicação e o exemplo antes de tentar novamente."},{"type":"recap","items":["Escolher elementos HTML adequados para títulos, parágrafos, ênfase, agrupamento e conteúdo genérico, evitando marcação sem significado.","Escolha a tag pelo significado, não pelo estilo padrão.","Mantenha hierarquia de títulos coerente.","Use button para ações e a para navegação."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=3) and title='Tags e elementos HTML fundamentais';
update nexora.lessons set objective='Criar navegação, imagens acessíveis e listas estruturadas usando atributos adequados e texto alternativo útil.',estimated_minutes=34,lab_type='html',lab_config='{}'::jsonb,content='[{"type":"story","title":"Contexto","body":"Um card de produto possui imagem sem alt, um clique feito por div e características separadas por quebras de linha. O conteúdo existe, mas não é robusto."},{"type":"concept","title":"Links, imagens, listas e conteúdo semântico","body":"Links conectam recursos e devem ter destino e texto compreensíveis fora de contexto. Imagens precisam de alt quando transmitem informação; imagens decorativas podem usar alt vazio. Listas ul/ol expressam coleções e sequência. Esses elementos dão ao navegador e às tecnologias assistivas pistas que um conjunto de divs não oferece."},{"type":"mechanics","title":"Como aplicar","items":["Escreva textos de link que indiquem destino ou ação.","Use alt descritivo para informação visual relevante.","Use ul para coleções e ol para ordem significativa.","Evite usar imagem como única forma de comunicar informação essencial."]},{"type":"example","title":"Exemplo","body":"<a href=\"/cursos\">Ver catálogo de cursos</a>\\n<img src=\"curso.webp\" alt=\"Tela do projeto final do curso\">\\n<ul>\\n  <li>HTML semântico</li>\\n  <li>CSS responsivo</li>\\n</ul>","language":"html"},{"type":"mistake","title":"Erro comum","body":"Preencher alt com ''imagem'' ou repetir exatamente o texto ao lado. O texto alternativo deve cumprir a função informativa da imagem."},{"type":"guided","question":"Quando uma imagem é puramente decorativa, qual prática é adequada?","options":["Usar alt=\"\".","Omitir sempre o atributo alt.","Descrever todas as cores da imagem."],"answer":0,"hint":"Escolha a alternativa coerente com a estrutura ensinada.","feedback":"Correto. Você aplicou a decisão estrutural da aula.","feedback_incorrect":"Revise a explicação e o exemplo antes de tentar novamente."},{"type":"recap","items":["Criar navegação, imagens acessíveis e listas estruturadas usando atributos adequados e texto alternativo útil.","Escreva textos de link que indiquem destino ou ação.","Use alt descritivo para informação visual relevante.","Use ul para coleções e ol para ordem significativa."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=3) and title='Links, imagens, listas e conteúdo semântico';
update nexora.lessons set objective='Construir formulários com labels, tipos de campo, agrupamento e botões corretos, preparando dados claros para validação e envio.',estimated_minutes=38,lab_type='html',lab_config='{}'::jsonb,content='[{"type":"story","title":"Contexto","body":"Um formulário mostra placeholders, mas os campos não têm labels e o botão envia acidentalmente sempre que é clicado."},{"type":"concept","title":"Formulários e elementos interativos","body":"Formulários transformam entrada humana em dados. Cada controle precisa de nome, tipo e rótulo apropriados. label associado a input melhora clique e leitura assistiva. Tipos como email, number e date ajudam o navegador a oferecer teclado e validações básicas. O atributo name define a chave enviada. Botões devem declarar type para deixar clara a intenção."},{"type":"mechanics","title":"Como aplicar","items":["Associe label e input por for/id ou envolvendo o controle.","Escolha tipos coerentes com o dado.","Defina name para campos que serão enviados.","Use button type=\"submit\" para envio e type=\"button\" para ações locais."]},{"type":"example","title":"Exemplo","body":"<form>\\n  <label for=\"email\">E-mail</label>\\n  <input id=\"email\" name=\"email\" type=\"email\" required>\\n  <button type=\"submit\">Enviar</button>\\n</form>","language":"html"},{"type":"mistake","title":"Erro comum","body":"Usar placeholder como substituto de label. Ele desaparece durante a digitação e não oferece contexto persistente."},{"type":"guided","question":"Qual atributo define a chave do campo enviada com o formulário?","options":["name","class","placeholder"],"answer":0,"hint":"Escolha a alternativa coerente com a estrutura ensinada.","feedback":"Correto. Você aplicou a decisão estrutural da aula.","feedback_incorrect":"Revise a explicação e o exemplo antes de tentar novamente."},{"type":"recap","items":["Construir formulários com labels, tipos de campo, agrupamento e botões corretos, preparando dados claros para validação e envio.","Associe label e input por for/id ou envolvendo o controle.","Escolha tipos coerentes com o dado.","Defina name para campos que serão enviados."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=3) and title='Formulários e elementos interativos';
update nexora.lessons set objective='Estruturar páginas com landmarks e controles nativos que funcionem por teclado e comuniquem propósito a tecnologias assistivas.',estimated_minutes=40,lab_type='html',lab_config='{}'::jsonb,content='[{"type":"story","title":"Contexto","body":"A página está bonita com o mouse, mas um usuário de teclado não consegue identificar regiões nem acionar alguns controles."},{"type":"concept","title":"HTML semântico e acessibilidade","body":"Acessibilidade começa na estrutura. Elementos como header, nav, main, section, article, aside e footer criam landmarks compreensíveis. Controles nativos já trazem foco, semântica e interação de teclado. ARIA complementa HTML quando necessário, mas não deve substituir um elemento nativo adequado. Uma página semanticamente correta tende a ser mais fácil de testar, manter e indexar."},{"type":"mechanics","title":"Como aplicar","items":["Tenha um main principal por página.","Prefira elementos nativos a componentes simulados com div.","Preserve foco visível.","Use ARIA apenas quando o HTML sozinho não expressa a relação necessária."]},{"type":"example","title":"Exemplo","body":"<header>...</header>\\n<nav aria-label=\"Principal\">...</nav>\\n<main>\\n  <section aria-labelledby=\"titulo-cursos\">\\n    <h2 id=\"titulo-cursos\">Cursos</h2>\\n  </section>\\n</main>","language":"html"},{"type":"mistake","title":"Erro comum","body":"Adicionar role=\"button\" a uma div e imaginar que ela virou um botão completo. Ainda faltam foco, teclado e estados."},{"type":"guided","question":"Qual escolha oferece melhor base de acessibilidade para uma ação clicável?","options":["Usar <button>.","Usar <div onclick>.","Usar <span> com cor diferente."],"answer":0,"hint":"Escolha a alternativa coerente com a estrutura ensinada.","feedback":"Correto. Você aplicou a decisão estrutural da aula.","feedback_incorrect":"Revise a explicação e o exemplo antes de tentar novamente."},{"type":"recap","items":["Estruturar páginas com landmarks e controles nativos que funcionem por teclado e comuniquem propósito a tecnologias assistivas.","Tenha um main principal por página.","Prefira elementos nativos a componentes simulados com div.","Preserve foco visível."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=3) and title='HTML semântico e acessibilidade';
update nexora.lessons set objective='Aplicar estilos por seletores e prever qual regra vence considerando origem, especificidade e ordem na cascata.',estimated_minutes=38,lab_type='html',lab_config='{}'::jsonb,content='[{"type":"story","title":"Contexto","body":"Você altera uma cor no CSS, mas nada muda. Outra regra mais específica está vencendo e o problema não é o navegador."},{"type":"concept","title":"Introdução ao CSS: seletores e cascata","body":"CSS descreve como elementos são apresentados. Seletores escolhem alvos; declarações definem propriedades e valores. Quando múltiplas regras competem, a cascata decide o resultado considerando importância, origem, especificidade e ordem. Entender esse mecanismo é melhor do que aumentar seletor ou usar !important até ''funcionar''."},{"type":"mechanics","title":"Como aplicar","items":["Comece com seletores simples e previsíveis.","Use classes como unidade principal de estilização.","Inspecione estilos computados ao investigar conflitos.","Evite !important como solução padrão."]},{"type":"example","title":"Exemplo","body":"p{color:#cbd5e1}\\n.card p{color:#fff}\\n/* Em um p dentro de .card, a segunda regra é mais específica. */","language":"css"},{"type":"mistake","title":"Erro comum","body":"Responder a todo conflito aumentando a especificidade. Em pouco tempo o CSS vira uma disputa difícil de sobrescrever."},{"type":"guided","question":"Se duas regras válidas têm a mesma especificidade, qual tende a vencer?","options":["A que aparece depois.","A primeira sempre.","A que tem menos propriedades."],"answer":0,"hint":"Escolha a alternativa coerente com a estrutura ensinada.","feedback":"Correto. Você aplicou a decisão estrutural da aula.","feedback_incorrect":"Revise a explicação e o exemplo antes de tentar novamente."},{"type":"recap","items":["Aplicar estilos por seletores e prever qual regra vence considerando origem, especificidade e ordem na cascata.","Comece com seletores simples e previsíveis.","Use classes como unidade principal de estilização.","Inspecione estilos computados ao investigar conflitos."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=3) and title='Introdução ao CSS: seletores e cascata';
update nexora.lessons set objective='Calcular e controlar dimensões usando content, padding, border e margin e explicar como elementos participam do fluxo normal.',estimated_minutes=40,lab_type='html',lab_config='{}'::jsonb,content='[{"type":"story","title":"Contexto","body":"Um card definido com width:300px ocupa mais espaço do que esperado porque padding e borda foram somados à largura."},{"type":"concept","title":"Box model e fluxo de layout","body":"No box model, cada elemento possui conteúdo, padding, border e margin. Com box-sizing: content-box, width descreve apenas o conteúdo; com border-box, padding e borda entram no tamanho declarado. Além disso, elementos participam do fluxo normal conforme display e contexto. Entender caixa e fluxo resolve muitos ''bugs de alinhamento'' sem recorrer a posicionamento absoluto."},{"type":"mechanics","title":"Como aplicar","items":["Use border-box como padrão de projeto.","Diferencie espaço interno (padding) de externo (margin).","Entenda display block/inline antes de usar flex ou grid.","Inspecione a caixa real no DevTools."]},{"type":"example","title":"Exemplo","body":"*,*::before,*::after{box-sizing:border-box}\\n.card{width:300px;padding:24px;border:1px solid #334155}","language":"css"},{"type":"mistake","title":"Erro comum","body":"Compensar larguras erradas com valores negativos ou ajustes aleatórios sem verificar o box model."},{"type":"guided","question":"Com box-sizing:border-box, o padding faz parte da largura declarada?","options":["Sim.","Não.","Apenas em imagens."],"answer":0,"hint":"Escolha a alternativa coerente com a estrutura ensinada.","feedback":"Correto. Você aplicou a decisão estrutural da aula.","feedback_incorrect":"Revise a explicação e o exemplo antes de tentar novamente."},{"type":"recap","items":["Calcular e controlar dimensões usando content, padding, border e margin e explicar como elementos participam do fluxo normal.","Use border-box como padrão de projeto.","Diferencie espaço interno (padding) de externo (margin).","Entenda display block/inline antes de usar flex ou grid."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=3) and title='Box model e fluxo de layout';
update nexora.lessons set objective='Construir hierarquia visual legível usando contraste, escala tipográfica e sistema de espaçamento consistente.',estimated_minutes=38,lab_type='html',lab_config='{}'::jsonb,content='[{"type":"story","title":"Contexto","body":"A interface possui dez tamanhos de fonte e espaçamentos aleatórios. Nada está tecnicamente quebrado, mas a leitura parece desorganizada."},{"type":"concept","title":"Cores, tipografia e espaçamento","body":"Design visual em CSS funciona melhor como sistema. Uma escala pequena de tamanhos, pesos e line-heights cria hierarquia; tokens de espaçamento evitam números arbitrários; cores precisam de contraste suficiente e papéis definidos. Consistência reduz carga cognitiva e também simplifica manutenção, porque decisões se repetem por regra e não por improviso."},{"type":"mechanics","title":"Como aplicar","items":["Defina uma escala curta de tamanhos e pesos.","Use line-height confortável para texto corrido.","Crie tokens para espaçamento e cores recorrentes.","Teste contraste e não comunique estado apenas por cor."]},{"type":"example","title":"Exemplo","body":":root{--space-1:.5rem;--space-2:1rem;--text:#e5edf6;--muted:#9fb0c2}\\nbody{font-size:1rem;line-height:1.65;color:var(--text)}","language":"css"},{"type":"mistake","title":"Erro comum","body":"Escolher cor pela estética isolada e descobrir depois que texto, estados de erro ou foco não têm contraste suficiente."},{"type":"guided","question":"Qual prática reduz inconsistência de espaçamento em uma interface?","options":["Usar uma escala/tokens recorrentes.","Escolher um valor novo para cada bloco.","Usar apenas margin-left."],"answer":0,"hint":"Escolha a alternativa coerente com a estrutura ensinada.","feedback":"Correto. Você aplicou a decisão estrutural da aula.","feedback_incorrect":"Revise a explicação e o exemplo antes de tentar novamente."},{"type":"recap","items":["Construir hierarquia visual legível usando contraste, escala tipográfica e sistema de espaçamento consistente.","Defina uma escala curta de tamanhos e pesos.","Use line-height confortável para texto corrido.","Crie tokens para espaçamento e cores recorrentes."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=3) and title='Cores, tipografia e espaçamento';
update nexora.lessons set objective='Usar Flexbox para distribuir e alinhar itens em um eixo principal, controlando crescimento, quebra e alinhamento.',estimated_minutes=42,lab_type='html',lab_config='{}'::jsonb,content='[{"type":"story","title":"Contexto","body":"Uma barra de ações precisa alinhar texto à esquerda e botões à direita, adaptando-se quando a largura diminui."},{"type":"concept","title":"Flexbox","body":"Flexbox organiza itens em uma dimensão principal por vez. display:flex cria um flex container; flex-direction define o eixo; justify-content distribui ao longo do eixo principal; align-items atua no eixo cruzado. flex-grow, shrink e basis controlam espaço. wrap permite quebra. Ele é ideal para barras, grupos de botões, cards em linha e alinhamentos onde a relação principal é linear."},{"type":"mechanics","title":"Como aplicar","items":["Escolha o eixo antes de escolher propriedades de alinhamento.","Use gap para espaçamento entre itens.","Permita wrap quando o conteúdo pode não caber.","Evite larguras fixas desnecessárias em itens flexíveis."]},{"type":"example","title":"Exemplo","body":".toolbar{display:flex;align-items:center;justify-content:space-between;gap:1rem;flex-wrap:wrap}","language":"css"},{"type":"mistake","title":"Erro comum","body":"Trocar justify-content e align-items por tentativa e erro sem entender qual é o eixo principal atual."},{"type":"guided","question":"Em flex-direction:row, justify-content atua principalmente em qual eixo?","options":["Horizontal/principal.","Vertical/cruzado.","Profundidade z."],"answer":0,"hint":"Escolha a alternativa coerente com a estrutura ensinada.","feedback":"Correto. Você aplicou a decisão estrutural da aula.","feedback_incorrect":"Revise a explicação e o exemplo antes de tentar novamente."},{"type":"recap","items":["Usar Flexbox para distribuir e alinhar itens em um eixo principal, controlando crescimento, quebra e alinhamento.","Escolha o eixo antes de escolher propriedades de alinhamento.","Use gap para espaçamento entre itens.","Permita wrap quando o conteúdo pode não caber."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=3) and title='Flexbox';
update nexora.lessons set objective='Criar layouts bidimensionais com linhas, colunas, repeat, minmax e auto-fit sem depender de larguras rígidas.',estimated_minutes=44,lab_type='html',lab_config='{}'::jsonb,content='[{"type":"story","title":"Contexto","body":"Uma grade de cards deve usar tantas colunas quanto couberem e cair para uma coluna em telas menores sem dezenas de breakpoints."},{"type":"concept","title":"CSS Grid","body":"CSS Grid modela linhas e colunas simultaneamente. grid-template-columns define trilhas; fr distribui espaço; minmax combina limites; repeat e auto-fit/auto-fill permitem grades adaptativas. Grid é especialmente útil quando itens precisam compartilhar alinhamento em duas dimensões, como dashboards, galerias e áreas principais com sidebar."},{"type":"mechanics","title":"Como aplicar","items":["Modele colunas pela necessidade do conteúdo.","Use minmax para permitir crescimento controlado.","Use gap em vez de margens entre células.","Não force número fixo de colunas quando a largura disponível varia muito."]},{"type":"example","title":"Exemplo","body":".cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem}","language":"css"},{"type":"mistake","title":"Erro comum","body":"Usar Grid para cada alinhamento simples. Para relações lineares, Flexbox pode ser mais direto."},{"type":"guided","question":"Qual combinação cria uma grade responsiva sem breakpoint explícito?","options":["repeat(auto-fit,minmax(...))","position:absolute em todos os cards","width:250px fixo"],"answer":0,"hint":"Escolha a alternativa coerente com a estrutura ensinada.","feedback":"Correto. Você aplicou a decisão estrutural da aula.","feedback_incorrect":"Revise a explicação e o exemplo antes de tentar novamente."},{"type":"recap","items":["Criar layouts bidimensionais com linhas, colunas, repeat, minmax e auto-fit sem depender de larguras rígidas.","Modele colunas pela necessidade do conteúdo.","Use minmax para permitir crescimento controlado.","Use gap em vez de margens entre células."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=3) and title='CSS Grid';
update nexora.lessons set objective='Escolher entre static, relative, absolute, fixed e sticky e controlar empilhamento sem criar conflitos arbitrários de z-index.',estimated_minutes=40,lab_type='html',lab_config='{}'::jsonb,content='[{"type":"story","title":"Contexto","body":"Um menu sticky desaparece atrás de um card e alguém tenta resolver com z-index:999999. A origem real está no contexto de empilhamento."},{"type":"concept","title":"Posicionamento e camadas","body":"Position muda como um elemento participa do fluxo e a referência usada por propriedades top/right/bottom/left. Absolute sai do fluxo e se posiciona em relação ao ancestral posicionado; fixed usa a viewport; sticky alterna entre fluxo e fixação conforme o scroll. z-index atua dentro de contextos de empilhamento, que podem ser criados por várias propriedades. Números gigantes não atravessam necessariamente esses contextos."},{"type":"mechanics","title":"Como aplicar","items":["Use posicionamento apenas quando o fluxo normal não resolve.","Dê position:relative ao contêiner de elementos absolute.","Reserve fixed/sticky para comportamentos que justificam persistência.","Investigue stacking context antes de elevar z-index."]},{"type":"example","title":"Exemplo","body":".card{position:relative}.badge{position:absolute;top:.75rem;right:.75rem}.tabs{position:sticky;top:0;z-index:10}","language":"css"},{"type":"mistake","title":"Erro comum","body":"Usar position:absolute para montar todo o layout. O conteúdo deixa de empurrar outros elementos e quebra facilmente em telas menores."},{"type":"guided","question":"Um elemento absolute costuma usar como referência qual ancestral?","options":["O ancestral posicionado mais próximo.","Sempre o body.","Sempre o elemento anterior."],"answer":0,"hint":"Escolha a alternativa coerente com a estrutura ensinada.","feedback":"Correto. Você aplicou a decisão estrutural da aula.","feedback_incorrect":"Revise a explicação e o exemplo antes de tentar novamente."},{"type":"recap","items":["Escolher entre static, relative, absolute, fixed e sticky e controlar empilhamento sem criar conflitos arbitrários de z-index.","Use posicionamento apenas quando o fluxo normal não resolve.","Dê position:relative ao contêiner de elementos absolute.","Reserve fixed/sticky para comportamentos que justificam persistência."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=3) and title='Posicionamento e camadas';
update nexora.lessons set objective='Construir interfaces mobile-first que se adaptem ao conteúdo e usar media queries somente quando a composição realmente precisa mudar.',estimated_minutes=44,lab_type='html',lab_config='{}'::jsonb,content='[{"type":"story","title":"Contexto","body":"O desktop funciona, mas no celular há overflow horizontal, texto minúsculo e botões comprimidos. Reduzir tudo proporcionalmente não resolve."},{"type":"concept","title":"Responsividade e media queries","body":"Responsividade é adaptação de layout, tipografia e interação à largura e ao contexto, não apenas redução. Uma abordagem mobile-first começa com a estrutura essencial e adiciona complexidade quando existe espaço. Media queries devem responder a pontos em que o conteúdo deixa de funcionar. Unidades flexíveis, max-width, minmax e wrap resolvem grande parte da adaptação sem muitos breakpoints."},{"type":"mechanics","title":"Como aplicar","items":["Comece pela menor largura suportada.","Procure overflow e alvos de toque antes de estética.","Prefira limites baseados no conteúdo.","Teste várias larguras, não apenas um celular e um desktop."]},{"type":"example","title":"Exemplo","body":".layout{display:grid;gap:1rem}\\n@media(min-width:820px){.layout{grid-template-columns:2fr 1fr}}","language":"css"},{"type":"mistake","title":"Erro comum","body":"Criar um CSS desktop rígido e depois tentar consertar tudo com dezenas de media queries max-width."},{"type":"guided","question":"O que deve definir um breakpoint útil?","options":["O ponto em que o conteúdo/composição deixa de funcionar bem.","O modelo de celular mais popular.","Um número aleatório repetido."],"answer":0,"hint":"Escolha a alternativa coerente com a estrutura ensinada.","feedback":"Correto. Você aplicou a decisão estrutural da aula.","feedback_incorrect":"Revise a explicação e o exemplo antes de tentar novamente."},{"type":"recap","items":["Construir interfaces mobile-first que se adaptem ao conteúdo e usar media queries somente quando a composição realmente precisa mudar.","Comece pela menor largura suportada.","Procure overflow e alvos de toque antes de estética.","Prefira limites baseados no conteúdo."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=3) and title='Responsividade e media queries';
update nexora.lessons set objective='Aplicar transições e animações como feedback de estado, respeitando desempenho e preferências de movimento reduzido.',estimated_minutes=38,lab_type='html',lab_config='{}'::jsonb,content='[{"type":"story","title":"Contexto","body":"Todos os cards pulam, giram e deslizam ao mesmo tempo. A interface parece ativa, mas o movimento compete com a tarefa do usuário."},{"type":"concept","title":"Transições e animações com propósito","body":"Movimento deve comunicar mudança, relação ou feedback. Transition suaviza alteração entre estados; animation executa keyframes. Propriedades como transform e opacity costumam ter melhor desempenho do que animar layout. Duração curta e easing coerente ajudam a percepção sem atrasar. A preferência prefers-reduced-motion deve ser respeitada para usuários sensíveis a movimento."},{"type":"mechanics","title":"Como aplicar","items":["Anime mudança de estado, não decoração constante.","Prefira transform e opacity.","Mantenha durações curtas para interações frequentes.","Ofereça comportamento reduzido com prefers-reduced-motion."]},{"type":"example","title":"Exemplo","body":".button{transition:transform .16s ease}.button:hover{transform:translateY(-1px)}\\n@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}","language":"css"},{"type":"mistake","title":"Erro comum","body":"Usar animação para compensar falta de hierarquia visual. Movimento não substitui clareza."},{"type":"guided","question":"Qual propriedade é geralmente mais adequada para animação performática?","options":["transform","width em loop contínuo","top em centenas de elementos"],"answer":0,"hint":"Escolha a alternativa coerente com a estrutura ensinada.","feedback":"Correto. Você aplicou a decisão estrutural da aula.","feedback_incorrect":"Revise a explicação e o exemplo antes de tentar novamente."},{"type":"recap","items":["Aplicar transições e animações como feedback de estado, respeitando desempenho e preferências de movimento reduzido.","Anime mudança de estado, não decoração constante.","Prefira transform e opacity.","Mantenha durações curtas para interações frequentes."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=3) and title='Transições e animações com propósito';
update nexora.lessons set objective='Organizar estilos por componentes, estados e tokens, reduzindo acoplamento entre páginas e evitando seletores frágeis.',estimated_minutes=42,lab_type='html',lab_config='{}'::jsonb,content='[{"type":"story","title":"Contexto","body":"Uma alteração na classe .title quebra três páginas porque cada uma esperava uma variação diferente do mesmo seletor global."},{"type":"concept","title":"Organização de CSS e componentes","body":"CSS escalável precisa de fronteiras. Tokens concentram decisões globais; componentes agrupam estrutura visual reutilizável; variantes e estados tornam diferenças explícitas. Seletores dependentes de uma árvore profunda criam acoplamento e dificultam mover componentes. Uma boa organização permite localizar onde uma regra vive e prever seu alcance."},{"type":"mechanics","title":"Como aplicar","items":["Separe tokens globais de componentes.","Prefira classes de componente a seletores estruturais longos.","Modele estados com classes ou atributos claros.","Remova regras mortas ao evoluir o componente."]},{"type":"example","title":"Exemplo","body":":root{--radius-card:16px}.card{border-radius:var(--radius-card)}.card__title{font-size:1.25rem}.card[data-state=\"selected\"]{outline:2px solid #2878ff}","language":"css"},{"type":"mistake","title":"Erro comum","body":"Criar nomes genéricos globais como .title, .box e .blue usados com significados diferentes em dezenas de lugares."},{"type":"guided","question":"Qual abordagem reduz acoplamento de CSS?","options":["Classes de componente com responsabilidade clara.","Seletores de cinco níveis dependentes da árvore.","!important global."],"answer":0,"hint":"Escolha a alternativa coerente com a estrutura ensinada.","feedback":"Correto. Você aplicou a decisão estrutural da aula.","feedback_incorrect":"Revise a explicação e o exemplo antes de tentar novamente."},{"type":"recap","items":["Organizar estilos por componentes, estados e tokens, reduzindo acoplamento entre páginas e evitando seletores frágeis.","Separe tokens globais de componentes.","Prefira classes de componente a seletores estruturais longos.","Modele estados com classes ou atributos claros."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=3) and title='Organização de CSS e componentes';
update nexora.lessons set objective='Integrar HTML semântico, CSS responsivo, acessibilidade e organização de componentes em uma landing page publicável e verificável.',estimated_minutes=60,lab_type='project',lab_config='{}'::jsonb,content='[{"type":"story","title":"Contexto","body":"O briefing pede uma landing page que funcione em mobile e desktop, tenha CTA claro, formulário acessível e não dependa de frameworks."},{"type":"concept","title":"Projeto: landing page responsiva","body":"O projeto fecha o módulo porque exige transformar decisões isoladas em uma composição coerente. A entrega deve ter estrutura semântica, hierarquia visual, layout adaptativo, controles acessíveis e CSS organizado. O critério não é apenas ''parecer bonita'': a página precisa sobreviver a diferentes larguras, teclado, conteúdo real e inspeção do código."},{"type":"mechanics","title":"Como aplicar","items":["Planeje a estrutura semântica antes do CSS.","Construa mobile-first e teste overflow continuamente.","Garanta foco, labels e contraste.","Revise arquivos, nomes e organização antes de publicar."]},{"type":"example","title":"Exemplo","body":"Entrega esperada: repositório + URL publicada + README curto com objetivo, estrutura e como testar responsividade/acessibilidade."},{"type":"mistake","title":"Erro comum","body":"Ajustar apenas a resolução usada durante o desenvolvimento. O projeto precisa funcionar entre os extremos, não só em dois screenshots."},{"type":"guided","question":"Qual evidência melhor demonstra que a landing é responsiva?","options":["Testes em uma faixa de larguras sem overflow e com composição funcional.","Um screenshot desktop.","Usar muitas media queries."],"answer":0,"hint":"Escolha a alternativa coerente com a estrutura ensinada.","feedback":"Correto. Você aplicou a decisão estrutural da aula.","feedback_incorrect":"Revise a explicação e o exemplo antes de tentar novamente."},{"type":"recap","items":["Integrar HTML semântico, CSS responsivo, acessibilidade e organização de componentes em uma landing page publicável e verificável.","Planeje a estrutura semântica antes do CSS.","Construa mobile-first e teste overflow continuamente.","Garanta foco, labels e contraste."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=3) and title='Projeto: landing page responsiva';

