insert into nexora.questions(assessment_id,prompt,question_type,options,correct_answer,feedback_correct,feedback_incorrect,difficulty,position) values(aid,'Se duas regras válidas têm a mesma especificidade, qual tende a vencer?','single_choice','[{"id":"a","label":"A que aparece depois."},{"id":"b","label":"A primeira sempre."},{"id":"c","label":"A que tem menos propriedades."}]'::jsonb,'{"id":"a"}'::jsonb,'Correto.','Revise a aula relacionada e tente novamente.',2,6);
