insert into nexora.questions(assessment_id,prompt,question_type,options,correct_answer,feedback_correct,feedback_incorrect,difficulty,position) values(aid,'Em flex-direction:row, justify-content atua principalmente em qual eixo?','single_choice','[{"id":"a","label":"Horizontal/principal."},{"id":"b","label":"Vertical/cruzado."},{"id":"c","label":"Profundidade z."}]'::jsonb,'{"id":"a"}'::jsonb,'Correto.','Revise a aula relacionada e tente novamente.',2,9);
insert into nexora.questions(assessment_id,prompt,question_type,options,correct_answer,feedback_correct,feedback_incorrect,difficulty,position) values(aid,'Qual combinação cria uma grade responsiva sem breakpoint explícito?','single_choice','[{"id":"a","label":"repeat(auto-fit,minmax(...))"},{"id":"b","label":"position:absolute em todos os cards"},{"id":"c","label":"width:250px fixo"}]'::jsonb,'{"id":"a"}'::jsonb,'Correto.','Revise a aula relacionada e tente novamente.',2,10);
