insert into nexora.projects(course_id,module_id,title,description,rubric,status,project_kind,xp_reward) values(cid,mid,'LC Programador Master — M3 • Boss Fight: Landing responsiva','Construir e publicar uma landing page sem framework, com HTML semântico, CSS organizado, formulário acessível e adaptação consistente entre mobile e desktop.','{"criteria":[{"name":"Semântica e acessibilidade","weight":25},{"name":"Responsividade","weight":30},{"name":"Qualidade visual","weight":20},{"name":"Organização do CSS","weight":15},{"name":"Publicação e README","weight":10}]}'::jsonb,'draft','boss_fight',450);
